# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# integration_equilibrium_initial_numbers ----
## Setup ----
data("data_big")
data_4_model <- FIMSFrame(data_big)
n_ages <- get_n_ages(data_4_model)
start_year <- get_start_year(data_4_model)
end_year <- get_end_year(data_4_model)
parameters <- setup_default_parameters(data = data_4_model)

# Returns the full-precision report and the estimates without optimizing
run_without_fitting <- function(parameters) {
  fit <- parameters |>
    initialize_fims(data = data_4_model) |>
    fit_fims(optimize = FALSE)
  output <- list(report = get_report(fit), estimates = get_estimates(fit))
  clear()
  output
}

# Numbers at age are folded with ages changing fastest, so the first n_ages
# values are the first year
first_year <- function(report, label) {
  report[[label]][[1]][seq_len(n_ages)]
}

## IO correctness ----
test_that("equilibrium initial numbers at age match the unfished equilibrium", {
  output <- run_without_fitting(parameters)

  #' @description Test that with log_init_rzero_offset and every deviation at 0, first-year numbers at age equal unfished numbers at age, including the plus group.
  expect_equal(
    object = first_year(output[["report"]], "numbers_at_age"),
    expected = first_year(output[["report"]], "unfished_numbers_at_age"),
    tolerance = 1e-12
  )

  #' @description Test that get_estimates() reports log_init_rzero_offset and no log_init_naa under the equilibrium option.
  expect_equal(
    object = sum(output[["estimates"]][["label"]] == "log_init_rzero_offset"),
    expected = 1
  )
  expect_false("log_init_naa" %in% output[["estimates"]][["label"]])
})

test_that("log_init_rzero_offset and deviations before the first year scale the first-year age structure", {
  offset <- 0.5
  # The cohort that recruited 2 years before the first year is the third age
  # in the first year
  deviation <- 0.3
  modified_parameters <- parameters |>
    dplyr::rows_update(
      tibble::tibble(label = "log_init_rzero_offset", value = offset),
      by = "label"
    ) |>
    dplyr::rows_update(
      tibble::tibble(
        label = "log_devs",
        timing = start_year - 2,
        value = deviation
      ),
      by = c("label", "timing")
    )
  output <- run_without_fitting(modified_parameters)
  log_ratio <- log(
    first_year(output[["report"]], "numbers_at_age") /
      first_year(output[["report"]], "unfished_numbers_at_age")
  )
  expected_log_ratio <- rep(offset, n_ages)
  expected_log_ratio[3] <- offset + deviation

  #' @description Test that every age is scaled by exp(log_init_rzero_offset) and only the cohort with a deviation is also scaled by exp(deviation).
  expect_equal(
    object = log_ratio,
    expected = expected_log_ratio,
    tolerance = 1e-12
  )
})

test_that("the first-year recruitment uses the log_devs entry for the first year", {
  deviation <- 0.2
  modified_parameters <- parameters |>
    dplyr::rows_update(
      tibble::tibble(label = "log_devs", timing = start_year, value = deviation),
      by = c("label", "timing")
    )
  output <- run_without_fitting(modified_parameters)

  #' @description Test that the youngest age in the first year is unfished recruitment times exp(deviation of the first year).
  expect_equal(
    object = first_year(output[["report"]], "numbers_at_age")[1],
    expected = exp(dplyr::filter(parameters, label == "log_rzero")[["value"]]) *
      exp(deviation),
    tolerance = 1e-12
  )

  later_year <- start_year + 4
  shifted_parameters <- parameters |>
    dplyr::rows_update(
      tibble::tibble(label = "log_devs", timing = later_year, value = deviation),
      by = c("label", "timing")
    )
  base_recruitment <- run_without_fitting(parameters)[["report"]][[
    "expected_recruitment"
  ]][[1]]
  shifted_recruitment <- run_without_fitting(shifted_parameters)[["report"]][[
    "expected_recruitment"
  ]][[1]]
  year_index <- later_year - start_year + 1

  #' @description Test that a deviation with a timing after the first year changes recruitment in that year and not in earlier years.
  expect_equal(
    object = shifted_recruitment[year_index] / base_recruitment[year_index],
    expected = exp(deviation),
    tolerance = 1e-12
  )
  expect_equal(
    object = shifted_recruitment[seq_len(year_index - 1)],
    expected = base_recruitment[seq_len(year_index - 1)]
  )
})

test_that("log_devs before the first year are reported with year_i of 0 or less", {
  estimates <- run_without_fitting(parameters)[["estimates"]]
  log_devs <- dplyr::filter(estimates, label == "log_devs")

  #' @description Test that the reported year_i of each deviation is its timing relative to the first year, which is 1.
  expect_equal(
    object = log_devs[["year_i"]],
    expected = (start_year - n_ages + 2):end_year - start_year + 1
  )
})

## Edge handling ----
test_that("removed deviations before the first year add no recruitment likelihood terms", {
  parameters_no_devs <- parameters |>
    dplyr::filter(!(label == "log_devs" & timing < start_year))
  output <- run_without_fitting(parameters_no_devs)
  log_devs <- dplyr::filter(output[["estimates"]], label == "log_devs")

  #' @description Test that without deviations before the first year, log_devs run from the first year to the last year.
  expect_equal(object = log_devs[["year_i"]], expected = seq_len(end_year - start_year + 1))

  # lpdf is the total log density of the recruitment process, repeated on
  # each row, and every remaining deviation is 0
  log_sd <- dplyr::filter(
    output[["estimates"]],
    module_name == "Recruitment",
    label == "log_sd"
  )[["estimated"]]
  #' @description Test that the recruitment log density is n_years normal terms at 0, so removed rows add no term that could pull log_sd toward 0.
  expect_equal(
    object = log_devs[["lpdf"]][1],
    expected = (end_year - start_year + 1) *
      dnorm(0, mean = 0, sd = exp(log_sd), log = TRUE),
    # The JSON output keeps 6 significant digits
    tolerance = 1e-5
  )

  #' @description Test that with the deviations before the first year removed and the rest at 0, first-year numbers at age equal unfished numbers at age.
  expect_equal(
    object = first_year(output[["report"]], "numbers_at_age"),
    expected = first_year(output[["report"]], "unfished_numbers_at_age"),
    tolerance = 1e-12
  )
})

test_that("free initial numbers at age still use log_init_naa", {
  free_parameters <- setup_default_parameters(
    data = data_4_model,
    initial_numbers = "free"
  )
  output <- run_without_fitting(free_parameters)

  #' @description Test that free first-year numbers at age are exp(log_init_naa).
  expect_equal(
    object = first_year(output[["report"]], "numbers_at_age"),
    expected = exp(dplyr::filter(free_parameters, label == "log_init_naa")[["value"]]),
    tolerance = 1e-12
  )

  #' @description Test that free estimates report log_init_naa and no log_init_rzero_offset.
  expect_equal(
    object = sum(output[["estimates"]][["label"]] == "log_init_naa"),
    expected = n_ages
  )
  expect_false("log_init_rzero_offset" %in% output[["estimates"]][["label"]])
})

test_that("equilibrium initial numbers at age are estimable", {
  testthat::skip_if(
    Sys.getenv("RUN_SLOW_TESTS") != "true",
    "Skipping: RUN_SLOW_TESTS is not set to true."
  )
  fit <- parameters |>
    initialize_fims(data = data_4_model) |>
    fit_fims(optimize = TRUE)
  estimates <- get_estimates(fit)
  clear()
  initial_devs <- dplyr::filter(estimates, label == "log_devs", year_i <= 0)

  #' @description Test that the deviations before the first year get finite standard errors from data_big.
  expect_true(all(is.finite(initial_devs[["uncertainty"]])))
  expect_equal(object = nrow(initial_devs), expected = n_ages - 2)
})

## Error handling ----
test_that("initialize_fims() checks how initial numbers at age are set", {
  #' @description Test that a gap in log_devs before the first year returns an informative error.
  expect_error(
    object = parameters |>
      dplyr::filter(!(label == "log_devs" & timing == start_year - 3)) |>
      initialize_fims(data = data_4_model),
    regexp = "log_devs"
  )
  clear()

  #' @description Test that a deviation for the plus group cohort returns an informative error.
  expect_error(
    object = parameters |>
      dplyr::bind_rows(
        dplyr::filter(parameters, label == "log_devs", timing == start_year) |>
          dplyr::mutate(timing = start_year - n_ages + 1)
      ) |>
      initialize_fims(data = data_4_model),
    regexp = "log_devs"
  )
  clear()

  #' @description Test that having both log_init_naa and log_init_rzero_offset returns an informative error.
  expect_error(
    object = parameters |>
      dplyr::bind_rows(
        setup_default_parameters(data = data_4_model, initial_numbers = "free") |>
          dplyr::filter(label == "log_init_naa")
      ) |>
      initialize_fims(data = data_4_model),
    regexp = "exactly one"
  )
  clear()

  #' @description Test that log_r recruitment with equilibrium initial numbers at age returns an informative error.
  expect_error(
    object = parameters |>
      dplyr::mutate(label = dplyr::if_else(label == "log_devs", "log_r", label)) |>
      initialize_fims(data = data_4_model),
    regexp = "cannot be used with equilibrium"
  )
  clear()

  #' @description Test that a free population with log_devs set up for an equilibrium start returns an informative error instead of putting deviations on the wrong years.
  expect_error(
    object = parameters |>
      dplyr::filter(module_name != "Population") |>
      dplyr::bind_rows(
        setup_default_Population(
          data = data_4_model,
          log_init_naa = 10,
          initial_numbers = "free"
        )
      ) |>
      initialize_fims(data = data_4_model),
    regexp = "log_devs"
  )
  clear()
})
